SELECT CASE WHEN budget >= 4302000 THEN 'high' WHEN budget >= 1328000 THEN 'mid' ELSE 'low' END AS budget_bucket, location, dept_name, MAX(budget) - MIN(budget) AS budget_range FROM departments WHERE dept_name != 'Finance' AND dept_name NOT IN ('HR', 'Finance') AND location NOT IN ('Chiang Mai', 'New York') GROUP BY budget_bucket, location, dept_name HAVING MAX(budget) - MIN(budget) > 23 ORDER BY dept_name ASC, budget_range DESC
